/* One particle curtain covers the themes, then disperses on an unclipped layer. */
(()=>{
const section=document.getElementById('chapters');if(!section)return;const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');if(!ctx)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,content=[...section.children].filter(el=>el.matches('.section-head,.chapter-layout')),cover=document.createElement('div'),button=document.createElement('button');cover.className='theme-particle-cover';button.className='theme-particle-trigger';button.type='button';button.setAttribute('aria-label','Click here to reveal The Three Themes');const label=document.createElement('span');label.className='theme-reveal-label';label.textContent='CLICK HERE';button.append(label);canvas.setAttribute('aria-hidden','true');cover.append(canvas,button);section.append(cover);content.forEach(el=>el.inert=true);section.classList.add('theme-locked');
let balls=[],w=0,h=0,raf=0,last=0,visible=false,opened=false,sky=null,skyCtx=null,observer=null;let dpr=Math.min(devicePixelRatio||1,2);
function measure(){if(opened)return;const r=section.getBoundingClientRect();w=r.width;h=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);balls=[];const step=w<600?8:9;for(let y=step/2;y<h;y+=step)for(let x=step/2;x<w;x+=step)balls.push({x,y,size:1.1+Math.random()*1.25,glow:false,seed:Math.random()*6.28});
const mask=document.createElement('canvas');mask.width=Math.ceil(w);mask.height=Math.ceil(h);const m=mask.getContext('2d');m.fillStyle='#fff';m.font=`600 ${Math.min(56,Math.max(27,w*.045))}px Arial`;m.textAlign='center';m.textBaseline='middle';const cy=Math.min(h*.48,innerHeight*.49);m.fillText('CLICK HERE',w/2,cy);const image=m.getImageData(0,0,mask.width,mask.height).data;for(let y=Math.max(0,Math.floor(cy-45));y<Math.min(h,cy+45);y+=3)for(let x=0;x<w;x+=3)if(image[(y*mask.width+x)*4+3]>100)balls.push({x,y,size:1.12,glow:true,seed:Math.random()*6.28});cover.classList.add('particle-cover-ready');paint(performance.now());queue()}
function paint(now){ctx.clearRect(0,0,w,h);ctx.fillStyle='#14181e';ctx.fillRect(0,0,w,h);for(const b of balls){const glow=b.glow,pulse=.7+.3*Math.sin(now*.0017+b.seed*.2);ctx.fillStyle=glow?`rgba(201,230,255,${pulse})`:'rgba(135,160,190,.72)';ctx.beginPath();ctx.arc(b.x,b.y,b.size,0,Math.PI*2);ctx.fill();if(glow){ctx.fillStyle=`rgba(145,202,255,${pulse*.075})`;ctx.beginPath();ctx.arc(b.x,b.y,5.5,0,Math.PI*2);ctx.fill()}}}
function reveal(e){if(opened)return;opened=true;const r=section.getBoundingClientRect(),cx=(e&&e.clientX?e.clientX:r.left+w/2),cy=(e&&e.clientY?e.clientY:r.top+Math.min(h*.48,innerHeight*.49));sky=document.createElement('canvas');sky.className='theme-explosion-layer';sky.setAttribute('aria-hidden','true');document.body.append(sky);skyCtx=sky.getContext('2d');sizeSky();
for(const b of balls){b.x+=r.left;b.y+=r.top+scrollY;const dx=b.x-cx,dy=b.y-(cy+scrollY),a=Math.atan2(dy,dx)+(Math.random()-.5)*.35,speed=(180+Math.random()*850)*(reduced?.22:1);b.vx=Math.cos(a)*speed;b.vy=Math.sin(a)*speed-90;b.age=0;b.life=reduced?1.2:3.2+Math.random()*3.4}
section.classList.remove('theme-locked');section.classList.add('theme-opening');content.forEach(el=>el.inert=false);cover.remove();observer?.disconnect();setTimeout(()=>section.querySelector('[role="tab"][aria-selected="true"]')?.focus({preventScroll:true}),400);last=0;queue()}
function sizeSky(){if(!sky)return;const d=Math.min(devicePixelRatio||1,2);sky.width=Math.round(innerWidth*d);sky.height=Math.round(innerHeight*d);skyCtx.setTransform(d,0,0,d,0,0)}
function frame(now){raf=0;if(!opened){if(visible){paint(now);if(!reduced)queue()}return}const dt=Math.min(.035,Math.max(.001,(now-(last||now-16))/1000));last=now;skyCtx.clearRect(0,0,innerWidth,innerHeight);let active=0;const drag=Math.exp(-.2*dt);
for(const b of balls){if(b.age>=b.life)continue;b.age+=dt;active++;b.vx*=drag;b.vy=b.vy*drag+38*dt;b.x+=b.vx*dt;b.y+=b.vy*dt;const y=b.y-scrollY;if(y<-20||y>innerHeight+20||b.x<-20||b.x>innerWidth+20)continue;const alpha=Math.pow(Math.max(0,1-b.age/b.life),1.3);skyCtx.fillStyle=b.glow?`rgba(201,230,255,${alpha})`:`rgba(145,181,224,${alpha*.8})`;skyCtx.beginPath();skyCtx.arc(b.x,y,b.size,0,Math.PI*2);skyCtx.fill()}
if(active)queue();else{sky.remove();balls=[];section.classList.remove('theme-opening');removeEventListener('resize',onResize)}}
function queue(){if(!raf)raf=requestAnimationFrame(frame)}function onResize(){if(opened)sizeSky();else measure()}
button.onclick=reveal;observer=new ResizeObserver(()=>{if(!opened)measure()});observer.observe(section);new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)queue()},{rootMargin:'100px'}).observe(section);addEventListener('resize',onResize);document.fonts.ready.then(()=>{if(!opened)measure()});measure();
})();
